INSERT INTO budget_occupation(tenant_id,report_id,employee_id,application_id,target_digest,version,status,pending_operation_id,state_json)
SELECT tenant_id,id,employee_id,application_id,#{targetDigest},1,'UNFUNDED',#{pendingOperationId},#{stateJson} FROM expense_report
WHERE tenant_id=#{tenantId} AND id=#{reportId} AND employee_id=#{employeeId}
